def read_deck(configuration=None):
    paths = []
    raw_path = (configuration or {}).get('__raw_path__')
    if raw_path:
        paths.append(os.path.join(os.path.dirname(os.path.abspath(raw_path)), 'deck.csv'))
    module_path = globals().get('__file__')
    if module_path:
        paths.append(os.path.join(os.path.dirname(os.path.abspath(module_path)), 'deck.csv'))
    paths.extend(['/kaggle_simulations/agent/deck.csv', 'deck.csv'])
    for path in paths:
        if os.path.isfile(path):
            with open(path, encoding='utf-8') as handle:
                ids = [int(s.strip()) for s in handle if s.strip()]
            if len(ids) != 60:
                raise ValueError('deck.csv must contain 60 card IDs')
            return ids
    raise FileNotFoundError('deck.csv not found')


def _player_state(obs):
    state = obs.get('current') or {}
    players = state.get('players') or []
    own_idx = state.get('yourIndex', 0)
    if own_idx not in (0, 1) or len(players) < 2:
        return state, {}, {}, 0
    return state, players[own_idx] or {}, players[1 - own_idx] or {}, own_idx


def _active(player):
    active = player.get('active') or []
    return active[0] if active and isinstance(active[0], dict) else {}


def _card_for_option(obs, option):
    state, mine, theirs, who = _player_state(obs)
    owner = option.get('playerIndex', who)
    players = (state.get('players') or [])
    if type(owner) is not int or not 0 <= owner < len(players):
        return {}
    player = players[owner] or {}
    area = option.get('area')
    index = option.get('index')
    if type(index) is not int or index < 0:
        return {}
    name = {1: 'deck', 2: 'hand', 3: 'discard', 4: 'active', 5: 'bench', 6: 'prize'}.get(area)
    values = player.get(name) if name else None
    if isinstance(values, list) and index < len(values) and isinstance(values[index], dict):
        return values[index]
    return {}


def _main_score(option, obs):
    typ = option.get('type')
    state, mine, theirs, who = _player_state(obs)
    turn_actions = state.get('turnActionCount', 0) or 0
    if typ == TYPE_ATTACK:
        damage = ATTACK_DAMAGE.get(option.get('attackId'), 0)
        opp_active = _active(theirs)
        hp = opp_active.get('hp')
        # Knockout check uses only printed base damage: it is a rough signal.
        knockout = (type(hp) in (int, float) and hp > 0 and damage >= hp)
        return 220 + damage / 10 if knockout else 92 + min(damage / 10, 35) + min(turn_actions, 30) / 2
    if typ == TYPE_EVOLVE:
        return 112
    if typ == TYPE_ATTACH:
        # Prefer energy on the active Pokémon, unless it is already attached.
        target = option.get('inPlayArea')
        return 116 if target == AREA_ACTIVE else 104
    if typ == TYPE_PLAY:
        # Legal plays develop the board, but the score is below a clear KO.
        bench_count = len(mine.get('bench') or [])
        return 108 if bench_count < 2 else 94
    if typ == TYPE_ABILITY:
        return 96
    if typ == TYPE_RETREAT:
        own_active = _active(mine)
        hp, max_hp = own_active.get('hp'), own_active.get('maxHp')
        if (type(hp) in (int, float) and type(max_hp) in (int, float)
                and max_hp > 0 and hp < max_hp * .30 and mine.get('bench')):
            return 120
        return 10
    if typ == TYPE_DISCARD:
        return 12
    if typ == TYPE_END:
        return -100
    return 25


def _option_score(option, obs):
    selection = obs.get('select') or {}
    selection_type = selection.get('type')
    context = selection.get('context')
    typ = option.get('type')
    if selection_type == SELECT_MAIN:
        return _main_score(option, obs)
    if selection_type == SELECT_YES_NO:
        if context == 42:  # Mulligan: prefer keeping a playable hand.
            return 10 if typ == TYPE_NO else 0
        if context in (43, 44):  # Optional activation/effect.
            return 10 if typ == TYPE_YES else 0
        return 2 if typ == TYPE_YES else 1
    if selection_type == SELECT_COUNT:
        return float(option.get('number', 0) or 0)
    if selection_type == SELECT_ENERGY:
        # During energy discards, spend bench energy first if available.
        if context == 30:
            return 5 if option.get('area') == AREA_BENCH else 0
        return 5 if option.get('area') == AREA_ACTIVE else 2
    if selection_type == SELECT_CARD:
        card = _card_for_option(obs, option)
        cid = card.get('id') or option.get('cardId')
        hp = CARD_HP.get(cid, 0)
        if context in (1, 2, 3, 4, 5, 6, 18, 19):
            return hp / 20.0  # Setup/switch: favor sturdier Pokémon.
        if context == 8:  # Discard: preserve higher-HP Pokémon if possible.
            return -hp / 20.0
        if context in (13, 14, 15):  # Damage target: favor opponent targets.
            current = obs.get('current') or {}
            return 10 if option.get('playerIndex') != current.get('yourIndex') else 0
        if context in (21, 22):  # Attachment target: generally favor Active.
            return 10 if option.get('area') == AREA_ACTIVE else 0
        return 0
    return 0


def agent(observation, configuration=None):
    selection = observation.get('select')
    if selection is None:
        return read_deck(configuration)
    options = selection.get('option') or []
    minimum = selection['minCount']
    maximum = selection['maxCount']
    if not 0 <= minimum <= maximum <= len(options):
        raise ValueError('Invalid selection bounds')
    # Match the accepted Day 2 behavior for number of selections.
    # Stable sort makes runs easier to debug. This is not a search policy.
    ranked = sorted(range(len(options)),
                    key=lambda i: (-_option_score(options[i], observation), i))
    return ranked[:maximum]
